const fs = require('fs');
const path = require('path');
function writeFile(relPath, content) {
  const full = path.join(__dirname, relPath);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, content, 'utf8');
  console.log('Updated', relPath);
}
writeFile("app/lib/auth.js", "import { supabase } from \"./supabaseClient\";\n\nconst SESSION_KEY = \"vexo_session\";\nconst ADMIN_SESSION_KEY = \"vexo_admin_session\";\n\nfunction safeParse(value) {\n  try {\n    return JSON.parse(value);\n  } catch {\n    return null;\n  }\n}\n\nexport async function signup({ username, email, phone, country, password }) {\n  const { data, error } = await supabase.auth.signUp({ email, password });\n\n  if (error) {\n    return { success: false, error: error.message };\n  }\n  if (!data.user) {\n    return { success: false, error: \"Please check your email to confirm your account, then sign in.\" };\n  }\n\n  await supabase.from(\"profiles\").update({ username, phone, country }).eq(\"id\", data.user.id);\n\n  localStorage.setItem(SESSION_KEY, JSON.stringify({ id: data.user.id, username, email, phone, country }));\n  return { success: true };\n}\n\nexport async function login({ email, password }) {\n  const { data, error } = await supabase.auth.signInWithPassword({ email, password });\n\n  if (error) {\n    return { success: false, error: \"Invalid email or password.\" };\n  }\n\n  const { data: profile } = await supabase\n    .from(\"profiles\")\n    .select(\"*\")\n    .eq(\"id\", data.user.id)\n    .single();\n\n  localStorage.setItem(\n    SESSION_KEY,\n    JSON.stringify({\n      id: data.user.id,\n      username: profile?.username || email.split(\"@\")[0],\n      email,\n      phone: profile?.phone || \"\",\n      country: profile?.country || \"\",\n    })\n  );\n  return { success: true };\n}\n\nexport function getSession() {\n  if (typeof window === \"undefined\") return null;\n  return safeParse(localStorage.getItem(SESSION_KEY));\n}\n\nexport async function logout() {\n  await supabase.auth.signOut();\n  localStorage.removeItem(SESSION_KEY);\n}\n\nexport async function adminLogin({ email, password }) {\n  const { data, error } = await supabase.auth.signInWithPassword({ email, password });\n\n  if (error) {\n    return { success: false, error: \"Invalid admin credentials.\" };\n  }\n\n  const { data: profile } = await supabase\n    .from(\"profiles\")\n    .select(\"*\")\n    .eq(\"id\", data.user.id)\n    .single();\n\n  if (!profile?.is_admin) {\n    await supabase.auth.signOut();\n    return { success: false, error: \"This account does not have admin access.\" };\n  }\n\n  localStorage.setItem(ADMIN_SESSION_KEY, JSON.stringify({ email }));\n  return { success: true };\n}\n\nexport function getAdminSession() {\n  if (typeof window === \"undefined\") return null;\n  return safeParse(localStorage.getItem(ADMIN_SESSION_KEY));\n}\n\nexport async function adminLogout() {\n  await supabase.auth.signOut();\n  localStorage.removeItem(ADMIN_SESSION_KEY);\n}\n");
